DROP TABLE "Tm_Approval";
CREATE COLUMN TABLE "Tm_Approval"
(
    "Id" INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL,
    "TransType"     NVARCHAR(50),
    "FormCode"      NVARCHAR(50),
    "ApprovalName"  NVARCHAR(50),
    "IsActive"      CHAR(1) CS_FIXEDSTRING,
    "CreatedDate"   LONGDATE CS_LONGDATE,
    "CreatedUser"   INTEGER CS_INT,
    "ModifiedDate"  LONGDATE CS_LONGDATE,
    "ModifiedUser"  INTEGER CS_INT,
    PRIMARY KEY ("Id")
)
UNLOAD PRIORITY 5
AUTO MERGE;

