DROP TABLE "Tx_StockOpname";
CREATE COLUMN TABLE "Tx_StockOpname"(
    "Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "TransType" NVARCHAR(50),
    "TransNo" NVARCHAR(50),
    
    "DocEntry" INT,
    "DocNum" NVARCHAR(50),
    "TransDate" TIMESTAMP,
    "PostingDate" TIMESTAMP,

    "WhsCode" NVARCHAR(50),
    "WhsName" VARCHAR(100),

    "Status" NVARCHAR(50),
    "ApprovalStatus" NVARCHAR(50),
    "IsAfterPosted" CHAR(1),
    "Comments" NVARCHAR(254),
    "CancelReason" NVARCHAR(254),    

    "IsApproval" CHAR(1),
    "ApprovalMessages" NVARCHAR(254),

    "CreatedDate" TIMESTAMP,
    "CreatedUser" INTEGER,
    "ModifiedDate" TIMESTAMP,
    "ModifiedUser" INTEGER
);

DROP TABLE "Tx_StockOpname_Item";
CREATE COLUMN TABLE "Tx_StockOpname_Item" (
    "Id" BIGINT,
    "DetId" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
    "ItemCode" NVARCHAR(50),
    "ItemName" NVARCHAR(200),
    "WhsCode" NVARCHAR(50),

    "Quantity" DECIMAL(21,2),
    "QtyVariance" DECIMAL(21,2),	
    "UomEntry" INTEGER,
    "Uom" NVARCHAR(50),
    "AcctCode" NVARCHAR(100),
    "AcctName" NVARCHAR(100),
	
    "UnitPriceTc" DECIMAL(21,2),
    "LineTotal" DECIMAL(21,2),
    
    "FreeText" NVARCHAR(254),
    "CreatedDate" TIMESTAMP,
    "CreatedUser" INTEGER,
    "ModifiedDate" TIMESTAMP,
    "ModifiedUser" INTEGER
);

DROP TABLE "Tx_StockOpname_Approval";
